{"source":"import csv
import json
import sys
from decimal import Decimal, ROUND_HALF_UP

def main():
    filename = sys.argv[1]

    # Read input bytes preserved
    with open(filename, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)

        categories = {}
        grand_total = Decimal('0')

        for row in reader:
            status = row['status'].strip().casefold()
            if status != 'paid':
                continue

            # Normalize category
            cat = row['category'].strip().casefold()
            if not cat:
                cat = 'uncategorized'

            # Parse amount and round each row
            amount = Decimal(row['amount']).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

            # Accumulate
            if cat not in categories:
                categories[cat] = Decimal('0')
            categories[cat] += amount
            grand_total += amount

        # Sort categories by normalized name
        sorted_cats = sorted(categories.items(), key=lambda x: x[0])

        # Build output
        result = {
            "categories": [
                {"category": name, "total": str(cat_total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))}
                for name, cat_total in sorted_cats
            ],
            "total": str(grand_total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        }

        print(json.dumps(result))

if __name__ == '__main__':
    main()
"}

